<?php
namespace App\Console\Commands; use App\Models\TrainingSession; use App\Services\TrainingInvitationService; use Illuminate\Console\Command;
class SendTrainingSessionReminders extends Command { protected $signature='sgsst:training-reminders'; protected $description='Envía recordatorios idempotentes de sesiones de capacitación'; public function handle(TrainingInvitationService$invitations):int{TrainingSession::whereIn('status',['called','attendance_open'])->where('scheduled_start_at','>',now())->with('attendanceEvent')->chunkById(100,function($sessions)use($invitations){foreach($sessions as$s){foreach(config('training.reminder_minutes',[1440,120]) as$minutes){$scheduled=$s->scheduled_start_at->copy()->subMinutes($minutes);$reminder=$s->reminders()->firstOrCreate(['minutes_before'=>$minutes],['scheduled_for'=>$scheduled,'status'=>'pending']);if($reminder->status==='pending'&&now()->gte($scheduled)){try{$invitations->send($s,$s->created_by,true);$reminder->update(['status'=>'sent','sent_at'=>now()]);}catch(\Throwable$e){$reminder->update(['status'=>'failed','error'=>$e->getMessage()]);}}}}});return self::SUCCESS;} }
